import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"21、【噬嗑】 震下离上","description":"周易口诀义 - 21、【噬嗑】 震下离上","frontmatter":{"title":"21、【噬嗑】 震下离上","description":"周易口诀义 - 21、【噬嗑】 震下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/023.md","filePath":"zh/classics/koujueyi/023.md"}'),r={name:"zh/classics/koujueyi/023.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_21、【噬嗑】-震下离上" tabindex="-1">21、【噬嗑】 震下离上 <a class="header-anchor" href="#_21、【噬嗑】-震下离上" aria-label="Permalink to “21、【噬嗑】 震下离上”">​</a></h1><p>彖曰：颐中有物曰「噬嗑」。噬嗑而亨，刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，「利用狱」也。</p><p>象曰：雷电，噬嗑。先王以明罚敕法。</p><p>初九：屦校灭趾，无咎。</p><p>象曰：「屦校灭趾」，不行也。</p><p>六二：噬肤灭鼻，无咎。</p><p>象曰：「噬肤灭鼻」，乘刚也。</p><p>六三：噬腊肉，遇毒，小吝，无咎。</p><p>象曰：「遇毒」，位不当也。</p><p>九四：噬乾胏，得金矢，利艰贞，吉。</p><p>象曰：「利艰贞吉」，未光也。</p><p>六五：噬乾肉，得黄金，贞厉，无咎。</p><p>象曰：「贞厉无咎」，得当也。</p><p>上九，何校灭耳，凶。</p><p>象曰：「何校灭耳」，聪不明也。</p><p>解读</p><p>「噬嗑，亨，利用狱」者，噬，啮也，嗑，合也；喻人口中有物则隔人隔塞正法，使正法不行，如口中有物，间啮而必通，刑去奸邪，正法无碍，故曰「利用狱」也。象曰：「雷电，噬嗑」，雷动而威，电照而明，明动相合，故曰「噬嗑」也。「先王以明罚𠡠法」者，敕，整理也，谓先王以明鉴之德，刑罚兼施，整齐法度也。</p><p>初九，履校灭趾，无咎者，屦犹履也，灭，没也；趾，足也；初九既居无位之地，是受刑之人，罪之尚微者也，若能于是时著械，没其趾足，而因惩戒尔后改行修德，故终身无咎，故云小惩大戒，此小人之福也。</p><p>六二，噬肤灭鼻，无咎。二为得位处中，所刑者当，故曰「噬肤灭鼻」。肤是柔脆之物，喻伏罪之人，然乘刚用刑，即刑人深矣。噬过其分，以至灭鼻，虽复过深而所刑者当，故曰「无咎」。</p><p>「六三，噬腊肉遇毒，小吝，无咎」者，以阴处阳，不正行刑，罪人不伏怨生，而不乘刚，不失顺道，虽有小吝，于义无咎，故曰「小吝，无咎」也。噬喻刑人，腊喻不伏，毒喻怨生。</p><p>「九四：噬乾胏，得金矢，利艰贞，吉」者，九四以阳失位，不正行刑，罪人不伏，故曰「噬乾胏」。乾胏，肉之乾者。「得金矢，利艰贞，吉」，金，刚也。矢，直也。虽刑不伏物，而能得其刚直也。既刚且直，又利艰固，不失其正，可以获吉也。</p><p>六五：噬乾肉，得黄金，贞厉，无咎。位既不正，有所刑人，人亦不伏，犹如噬啮乾坚之肉物，所以难噬也。「得黄金，贞厉，无咎」者，黄，中也；金，刚也。以其居中履刚，得其刚正之道，刚胜也。位既不正，刑戮得当，然则居贞以危，亦免咎也。</p><p>上九：何校灭耳，凶。何，担何也。校，枷锁也。灭，没也。上九喻人积恶之极，不能惩改，须至担何枷锁以没其耳，将至诛灭之凶，故云「恶积而不可揜，罪大而不可解」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
